const input = $input.first().json;
const headers = input.headers || {};
const supplied = headers['x-n8n-secret'] || headers['X-N8N-SECRET'];
if (!$env.N8N_WEBHOOK_SECRET || supplied !== $env.N8N_WEBHOOK_SECRET) throw new Error('Unauthorized clinical webhook');
const body = input.body || {};
const user_id = String(body.user_id || '').trim();
const conversation_id = String(body.conversation_id || ('clinical-' + Date.now())).trim();
const message = String(body.message || '').trim();
if (!user_id || !message || message.length > 10000) throw new Error('Invalid clinical payload');
return [{ json: { user_id, conversation_id, message, domain: 'medical' } }];

const input = $input.first().json;
const request = $('Validate Clinical Request').item.json;
let response = input.output || input.text || input.response || '';
if (typeof response !== 'string') response = JSON.stringify(response);
if (!response.trim()) response = 'I could not generate a safe answer. Please contact your clinician.';
return [{ json: { conversation_id: request.conversation_id, intent: 'medical_information', response, escalated: false, ticket_id: null, domain: 'medical', retrieved_docs: null } }];
